import base64

def b64url(s):
    return base64.urlsafe_b64decode((s or '')+'===').decode('utf-8','replace')

def parts(msg):
    ps=((msg.get('payload') or {}).get('parts') or [])
    out={'text':None,'html':None}
    for p in ps:
        mt=(p.get('mimeType') or '').lower()
        d=((p.get('body') or {}).get('data') or '')
        if mt=='text/plain' and d: out['text']=b64url(d)
        if mt=='text/html' and d: out['html']=b64url(d)
    return out
